import logging
import re
from itertools import count
from os import getcwd

from taf.transport.ssh import connect
from taf.ue.tm500.client import DetachScript5G, TMARadioCard, RadioCardConfigScript, LicenceServerConfig, CellSearch4G, \
    CellSearch5G, AttachScript5G
from taf.ue.tm500.client.parser import RadioCard
from taf.ue.tm500.client.setp_script_generator import SETPScript
from taf.ue.tm500.rci.interface import rci
from ute_common_abstract_core.network_elem_identification import UeIdentification
from ute_ue.exceptions import UeProcedureError
from ute_ue.lteue import LteUe

from taf.ue.plugin.viavi.viavi_config import Viavi_Config
from .pppd_connection import get_instance
from .viavi_data_transfer import ViaviDataTransfer

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

rci = rci()

# TODO: Move this to Viavi UEs Pool
"""
This dictionary holds information about whether radio configuration was already
done on a given machine, and how many ViaviUe objects use it.

Keys are hostnames, values are a refcount of ViaviUe objects.
ViaviUe.shutdown() should run only if the refcount reaches 0.

If machine's hostname is in this dictionary, then it means that:
    - TMA is connected to it ("#$$CONNECT")
    - RSET was executed
    - Radio configuration script was sent.

This ensures, that a machine is configured and disconnected only once
throughout different require_ue() calls.
"""
viavi_machines = {}
hostname_to_sender_reciever_map = {}

"""
This dictionary is a hostname:object mapping for RCI connections.
"""
rci_aliases = {}
attach_validation_regex_template = (r'(?=I: CMPI MTE 0 (EMM REGISTER|NR REGISTRATION) IND:UE Id:{ue_id}[^0-9])'
                                    r'.*?(?=(I: CMPI MTE 0 ACTIVATE IND: RETURN CODE:0|\Z))')
detach_validation_regex_template = (r'(?=I: CMPI MTE 0 (EMM DEREGISTER|NR DEREGISTRATION) IND:UE Id:{ue_id}[^0-9])'
                                    r'.*?(?=(I: CMPI MTE 0 ACTIVATE IND: RETURN CODE:0|\Z))')


class ViaviUe(LteUe):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    # Generates IDs for self.ne_id.
    # IDs for every other object should be different, as each object is a
    # separate logical UE for Viavi.
    _ID_GENERATOR = count()

    def __init__(self, name, hostname, port, script_paths=None,
                 data_transfer=None, script_parameters=None, attach_validation=None, detach_validation=None,
                 rci_timeout=None):

        """
        Definition of Abstract UE API

        :param name: name of UE to be stored inside UE object
        ue_config.yml,attach,detach & rc_config sample scripts are placed in test path of the module.
        User must specify the absolute path of above scripts in ue_config.yml file.
        rc_config script: Common TM500 commands for all the UE's must be specified in this script
        For example : config and cell search commands
        :Attribute name:
         pppd_server_type : User must specify pppd server type attribute in ue_config.yml. Currently supported are Linux and Windows.
         Default value is "Windows"

        """
        super(ViaviUe, self).__init__(name)
        self.hostname = hostname
        self.port = port
        self.scripts_path = script_paths
        self.script_parameters = script_parameters
        self._data_transfer = data_transfer
        self.rci_timeout = rci_timeout
        self.attach_validation = attach_validation
        self.detach_validation = detach_validation
        viavi_config = Viavi_Config.from_object_dict(self.__dict__)
        self.pppd_server_type = viavi_config._data_transfer.pppd_server_type
        self.pppoe_connected = False
        logger.debug("Current working directory is: {}".format(getcwd()))

        if self.hostname not in viavi_machines:
            self._create_connection()
            self._configure_machine()
            self.sender_receiver_info = self._get_epc_and_pppd_connections()
            self._clear_pppd_connection(self.sender_receiver_info["pppd_server"])
            hostname_to_sender_reciever_map[self.hostname] = self.sender_receiver_info
            self._cell_search()
        else:
            self._rci_alias = rci_aliases[self.hostname]

        self._add_machine_refcount()

        ute_ue_id = (('viavi', next(self._ID_GENERATOR)),
                     (self.hostname, self.port))
        self.ne_id = UeIdentification(identifiers=ute_ue_id,
                                      network_elem_type='UE',
                                      specific_for_tool='viavi')

    def _clear_pppd_connection(self, pppd_server):
        pppd_server.pppoe_disconnect(self._data_transfer['pppoe_conn_cmd'])
        self.pppoe_connected = False

    def _establish_pppd_connection(self, pppd_server):
        if not self.pppoe_connected:
            pppd_server.pppoe_connect(self._data_transfer['pppoe_conn_cmd'])
            self.pppoe_connected = True

    def _get_epc_and_pppd_connections(self):
        epc_pppd_details = {}
        epc_pppd_details["epc_ssh"] = connect(self._data_transfer['epc']['ip'], self._data_transfer['epc']['uname'],
                                              self._data_transfer['epc']['pwd'])

        pppd_server = get_instance(self._data_transfer['server']['ip'],
                                   self._data_transfer['server']['uname'],
                                   self._data_transfer['server']['pwd'],
                                   self.pppd_server_type)
        epc_pppd_details["pppd_ssh"] = pppd_server.ssh
        epc_pppd_details["pppd_server"] = pppd_server
        return epc_pppd_details

    def _create_connection(self):
        # TODO Use RCI objects instead of RobotFramework interface
        self._rci_alias = self.hostname
        self._ensure_connected()
        rci_aliases[self.hostname] = self._rci_alias

    def _configure_machine(self):
        rci.send_command('RSET', alias=self._rci_alias,
                         timeout=self.rci_timeout)
        rc_config_command_stream = self.generate_command_stream(operation='radio_card_config')
        self.rci_send_command_stream(rc_config_command_stream, alias=self._rci_alias,
                                     timeout=self.rci_timeout)

    def _cell_search(self):
        cell_search_command_stream = self.generate_command_stream(operation='cell_search')
        self.rci_send_command_stream(cell_search_command_stream, alias=self._rci_alias,
                                     timeout=self.rci_timeout)

    def _add_machine_refcount(self):
        if self.hostname not in viavi_machines:
            viavi_machines[self.hostname] = 0
        viavi_machines[self.hostname] += 1

    # TODO: This is ugly. This should not exist.
    def _ensure_connected(self):
        if self._rci_alias not in rci.cache:
            rci.connect_to(self.hostname, self.port, alias=self._rci_alias)
            rci.send_command('#$$CONNECT', alias=self._rci_alias, timeout=self.rci_timeout)

    def _get_ue_ip(self):
        return self.ue_ip

    def attach(self):
        """
        Perform attach on UE.

        Tested for Single UE. this version supports only single UE mode of operation.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If attach failed
        """
        self._ensure_connected()
        attach_command_stream = self.generate_command_stream("attach")
        attach_output = self.rci_send_command_stream(attach_command_stream, alias=self._rci_alias,
                                                     timeout=self.rci_timeout)

        if self.attach_validation is not None:
            self._output_contains_pattern(r'{}'.format(self.attach_validation), attach_output)
            match_string = attach_output
        else:
            match_string = self._validate('attach', attach_output,
                                          attach_validation_regex_template.format(ue_id='\\d*'))
        self.tm500_ue_id = self._output_contains_pattern(r'(?<=UE Id:)\d*', match_string)
        self.ue_ip = self._output_contains_pattern(r'(?<=IPv4 Address: )[0-9,.]*', match_string)
        self._data_transfer["pppoe_ue_ip"] = self.ue_ip

    def detach(self):
        """
        Perform detach on UE.

        No action if UE is already detached.

        Tested for Single UE. this version supports only single UE mode of operation.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If detach failed
        """
        self._ensure_connected()
        detach_command_stream = self.generate_command_stream("detach")
        detach_output = self.rci_send_command_stream(detach_command_stream, alias=self._rci_alias,
                                                     timeout=self.rci_timeout)

        if self.detach_validation is not None:
            self._output_contains_pattern(r'{}'.format(self.detach_validation), detach_output)
        else:
            match_string = self._validate('detach', detach_output,
                                          detach_validation_regex_template.format(ue_id=self.tm500_ue_id))
            self._output_contains_pattern(r'Detach Cause: UE Initiated', match_string)
        self.pppoe_connected = False

    @classmethod
    def _validate(cls, action_name, output, pattern):
        try:
            match_string = cls._output_contains_pattern(pattern, output)
        except Exception:
            exc_msg = ("{0} failed: {0} validation pattern not found in "
                       "the script output".format(action_name))
            raise UeProcedureError(exc_msg)
        return match_string

    @staticmethod
    def _output_contains_pattern(pattern, output):
        logger.debug("Looking for regex pattern \"{}\" "
                     "in the following output:".format(pattern))
        logger.debug(output)
        match = re.search(pattern, output, re.DOTALL)
        if not match:
            exc_msg = ("validation pattern not found in the script output")
            raise UeProcedureError(exc_msg)
        return match.group()

    def start_data_transfer(self, name, dt_definition):
        """
        Start data transfer operation.Currently Data Transfer Operation works only for first UE.

        :return: None
        """
        if self._data_transfer is not None:
            data_transfer = self._create_data_transfer(name, dt_definition)
            self._establish_pppd_connection(self.sender_receiver_info["pppd_server"])
            data_transfer.start()
            self.logger.info("Started '{}': {}".format(name, data_transfer))
            return data_transfer

    def stop_data_transfer(self, dt_name, dt_definition):
        """
        Stop Data Transfer Operation on UE.

        :param name: Name of Data Transfer that is assigned in Start Data Transfer keyword
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If stopping data transfer failed
        """
        data_transfer = self._create_data_transfer(dt_name, dt_definition)
        data_transfer.stop()
        self.logger.info("Stopped '{}': {}".format(dt_name, data_transfer))
        return data_transfer

    def verify_average_throughput(self, dt_name, dt_definition, tput_min, tput_max=None):
        """
        Verify if running throughput is in desired range: tput_min <-> tput_max

        If tput_max=None: Verify if running throughput is above desired threshold: tput_min

        :param name: name of data transfer to be verified
        :param tput_min: lower threshold for desired average data transfer throughput in string format. e.g. '1MBytes/sec'
        :param tput_max: upper threshold for desired average data transfer throughput in string format. e.g. '4MBytes/sec'
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.DataTransferVerificationFailure`: if verification fails
        """
        data_transfer = self._create_data_transfer(dt_name, dt_definition)
        data_transfer.verify_average_throughput(tput_min=tput_min, tput_max=tput_max)
        self.logger.info("verify Average Throughput '{}': {}".format(dt_name, data_transfer))
        return data_transfer

    def await_data_transfer_finish(self, dt_name, dt_definition):
        """
        Awaits completion of ongoing data transfer on UE.

        :param name: Name of Data Transfer that is assigned in Start Data Transfer keyword
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such ue_alias created before via require_ue
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If stopping data transfer failed
        :raises: :py:class:`ute_ue.exceptions.DataTransferCantWaitForeverException`: If this DT has 'forever' duration
        """
        data_transfer = self._create_data_transfer(dt_name, dt_definition)
        data_transfer.await_finish()
        self.logger.info("Await Data Transfer '{}': {}".format(dt_name, data_transfer))
        return data_transfer

    def _create_data_transfer(self, name, dt_definition):
        """
        Create data transfer operation

        :return: None
        """
        return ViaviDataTransfer(
            alias=self.name + name,
            dt_definition=dt_definition,
            configuration=self._data_transfer,
            rci_timeout=self.rci_timeout,
            sender_reciever_details=hostname_to_sender_reciever_map[self.hostname]
        )

    def shutdown(self):
        """Shutdown UE"""
        viavi_machines[self.hostname] -= 1
        if viavi_machines[self.hostname] <= 0:
            # Ensure correct refcount
            viavi_machines[self.hostname] = 0
            self._disconnect_ssh_connection()
            rci.disconnect(alias=self._rci_alias)

    def _disconnect_ssh_connection(self):
        hostname_to_sender_reciever_map[self.hostname]['epc_ssh'].disconnect()
        hostname_to_sender_reciever_map[self.hostname]['pppd_ssh'].disconnect()

    def rci_send_command_stream(self, command_stream, timeout=None, alias=None):
        output = ''
        for command in command_stream:
            output += rci.send_command(command, alias=self._rci_alias,
                                       timeout=self.rci_timeout)
        return output

    def generate_command_stream(self, operation):
        """

        :param operation: Valid values are radio_card_config, cell_search, attach, detach
        :return:
        """
        generator_mapping = {'detach': self.generate_detach_script,
                             'radio_card_config': self.generate_radio_card_config,
                             'cell_search': self.generate_cell_search_script,
                             'attach': self.generate_attach_script}
        command_stream = ''

        filename = self.scripts_path.get(operation)
        if filename:
            with open(filename, 'r') as f:
                command_stream = f.readlines()
        else:
            if self.script_parameters:
                if len(self.script_parameters.get(operation)) > 0:
                    command_stream = str(generator_mapping[operation](self.script_parameters.get(operation))).splitlines(True)
        return command_stream

    def generate_optional_param_string(self, config_dict, optional_param_list):
        param_string = {}
        for param in optional_param_list:
            if param in config_dict.keys():
                param_string[param] = config_dict.get(param)
        # param_string = param_string[:-2]
        return param_string

    def generate_detach_script(self, config_dict):
        ue_id = config_dict["ue_id"]
        script = DetachScript5G(ue_id, timeout=config_dict.get('timeout', 5))
        return str(script)

    def generate_radio_card_config(self, config_dict):
        optional_params = ["clk_ref_in", "clk_ref_out", "interface_mode",
                           "frequency_range", "subcarrier_spacing"]
        rc_config_script = ''
        rc_list = []
        for rc in config_dict['radio_card_list'].keys():
            rc_dict = config_dict['radio_card_list'][rc]
            radiocard = RadioCard(rc_dict.get("card"), rc_dict.get("slot"), rc_dict.get("chassis"),
                                  rc_dict.get("context"),
                                  rc_dict.get("load"), rc_dict.get("rf"),
                                  rc_dict.get("dl"), rc_dict.get("ul"))
            param_string = self.generate_optional_param_string(rc_dict, optional_params)
            if param_string:
                rc_list.append(TMARadioCard(radiocard, **param_string))
            else:
                rc_list.append(TMARadioCard(radiocard))

        config = RadioCardConfigScript(rc_list)
        rc_config_script += str(config)
        lc = ""
        if "licenceserver_ip" in config_dict.keys():
            lc = LicenceServerConfig(config_dict["licenceserver_ip"],
                                     licenceserver_port=config_dict.get("licenceserver_port", 5053))
        rc_config_script += str(lc)
        return rc_config_script

    def generate_cell_search_script(self, config_dict):
        optional_params4g = ["number_of_enb_transmit_antennas", "sub_frame_assignment", "special_subframe_patterns",
                             "system_bandwidth", "number_of_receive_antennas"]
        optional_params5g = ["uplink_bandwidth", "absolute_frequency_pointA", "absolute_frequency_SSB",
                             "uplink_carrier_frequency",
                             "number_of_receive_antennas", "frequencyShift7p5khz"]
        cell_search_script = ''
        if self.script_parameters.get('setParameters'):
            setParms = self.script_parameters.get('setParameters')
            cell_search_script += SETPScript(setParms)

        if config_dict.get("cell_search4g"):
            config = config_dict["cell_search4g"]
            param_string = self.generate_optional_param_string(config, optional_params4g)
            if param_string:
                cell_search_script += str(CellSearch4G(config.get("radio_context_Id"),
                                                       config.get("cell_Id"),
                                                       config.get("downlink_carrier_frequency"), param_string
                                                       )) + "\n"
            else:
                cell_search_script += str(CellSearch4G(config.get("radio_context_Id"),
                                                       config.get("cell_Id"),
                                                       config.get("downlink_carrier_frequency")
                                                       )) + "\n"
        config = config_dict["cell_search5g"]
        param_string = self.generate_optional_param_string(config, optional_params5g)
        if param_string:
            cell_search_script += str(CellSearch5G(config.get("radio_context_Id"),
                                                   config.get("cell_Id"),
                                                   config.get("downlink_carrier_frequency"),
                                                   config.get("system_bandwidth"),
                                                   config.get("gnb_downlink_carrier_frequency"),
                                                   config.get("ssb_subcarrier_spacing"), param_string
                                                   ))
        else:
            cell_search_script += str(CellSearch5G(config.get("radio_context_Id"),
                                                   config.get("cell_Id"),
                                                   config.get("downlink_carrier_frequency"),
                                                   config.get("system_bandwidth"),
                                                   config.get("gnb_downlink_carrier_frequency"),
                                                   config.get("ssb_subcarrier_spacing")
                                                   ))
        return cell_search_script

    def generate_attach_script(self, config_dict):
        ue_id = config_dict.get("ue_id")
        imsi = config_dict.get("imsi")
        pdn_id = config_dict.get("pdn_id")
        timeout = config_dict.get("timeout", 5)
        script = str(AttachScript5G(ue_id, imsi, pdn_id, timeout))
        return script
